(async () => {
  const pausa = (ms) => new Promise((r) => setTimeout(r, ms));
  let hecho = 'sin copiloto';
  for (const f of document.querySelectorAll('iframe')) {
    try { const d = f.contentDocument; if (!d || !/copiloto/.test(f.src)) continue;
      const b = [...d.querySelectorAll('button')].find((b) => b.innerText.trim() === 'Nueva conversación'); if (b) { b.click(); hecho = 'nueva' } } catch (e) {}
  }
  const acceso = [...document.querySelectorAll("nav[class*='panelList'] button")].find((b) => b.innerText.trim() === 'Acceso');
  if (acceso) acceso.click();
  await pausa(1500);
  return hecho;
})()
